#include "2mm.h"

extern "C" {

void kernel_2mm(
        double alpha,
        double beta,
        double tmp[ NI + 0][NJ + 0],
        double A[ NI + 0][NK + 0],
        double B[ NK + 0][NJ + 0],
        double C[ NJ + 0][NL + 0],
        double D[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=tmp    offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A      offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B      offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=C      offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=D      offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=alpha  bundle=control
#pragma HLS INTERFACE s_axilite port=beta   bundle=control
#pragma HLS INTERFACE s_axilite port=tmp    bundle=control
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=B      bundle=control
#pragma HLS INTERFACE s_axilite port=C      bundle=control
#pragma HLS INTERFACE s_axilite port=D      bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;

    // Local buffers to avoid repeated global memory accesses
    double local_tmp[NI][NJ];
    double local_A[NI][NK];
    double local_B[NK][NJ];
    double local_C[NJ][NL];
    double local_D[NI][NL];

#pragma HLS ARRAY_PARTITION variable=local_tmp cyclic factor=2 dim=2
#pragma HLS ARRAY_PARTITION variable=local_A   cyclic factor=2 dim=2
#pragma HLS ARRAY_PARTITION variable=local_B   cyclic factor=2 dim=2
#pragma HLS ARRAY_PARTITION variable=local_C   cyclic factor=2 dim=2
#pragma HLS ARRAY_PARTITION variable=local_D   cyclic factor=2 dim=2

    // Load A
    load_A: for (int i = 0; i < NI; i++)
        for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
            local_A[i][k] = A[i][k];
        }

    // Load B
    load_B: for (int k = 0; k < NK; k++)
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            local_B[k][j] = B[k][j];
        }

    // Compute tmp = alpha * A * B  (preserve serial FP reduction order)
    loop1_i: for (int i = 0; i < ni; i++) {
        loop1_j: for (int j = 0; j < nj; j++) {
            double acc = 0.0;
            loop1_k: for (int k = 0; k < nk; ++k) {
#pragma HLS PIPELINE II=1
                acc += alpha * local_A[i][k] * local_B[k][j];
            }
            local_tmp[i][j] = acc;
        }
    }

    // Store tmp back
    store_tmp: for (int i = 0; i < NI; i++)
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            tmp[i][j] = local_tmp[i][j];
        }

    // Load C
    load_C: for (int j = 0; j < NJ; j++)
        for (int l = 0; l < NL; l++) {
#pragma HLS PIPELINE II=1
            local_C[j][l] = C[j][l];
        }

    // Load D
    load_D: for (int i = 0; i < NI; i++)
        for (int l = 0; l < NL; l++) {
#pragma HLS PIPELINE II=1
            local_D[i][l] = D[i][l];
        }

    // Compute D = beta*D + tmp*C  (preserve serial FP reduction order)
    loop2_i: for (int i = 0; i < ni; i++) {
        loop2_j: for (int j = 0; j < nl; j++) {
            double acc = local_D[i][j] * beta;
            loop2_k: for (int k = 0; k < nj; ++k) {
#pragma HLS PIPELINE II=1
                acc += local_tmp[i][k] * local_C[k][j];
            }
            local_D[i][j] = acc;
        }
    }

    // Store D back
    store_D: for (int i = 0; i < NI; i++)
        for (int l = 0; l < NL; l++) {
#pragma HLS PIPELINE II=1
            D[i][l] = local_D[i][l];
        }
}

} // extern "C"

#include "3mm.h"

extern "C" {

void kernel_3mm(    
		double E[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double F[ NJ + 0][NL + 0],
		double C[ NJ + 0][NM + 0],
		double D[ NM + 0][NL + 0],
		double G[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=E offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=F offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=D offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=G offset=slave bundle=gmem6
#pragma HLS INTERFACE s_axilite port=E bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=F bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=D bundle=control
#pragma HLS INTERFACE s_axilite port=G bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;
    const int nm = NM;

    int i, j, k;

    // E = A * B  (ni x nj) = (ni x nk) * (nk x nj)
    for (i = 0; i < ni; i++)
        for (j = 0; j < nj; j++)
        {
            E[i][j] = 0.0;
            // Keep reduction serial to preserve FP bit-exact result
            for (k = 0; k < nk; ++k)
            {
#pragma HLS PIPELINE II=1
                E[i][j] += A[i][k] * B[k][j];
            }
        }

    // F = C * D  (nj x nl) = (nj x nm) * (nm x nl)
    for (i = 0; i < nj; i++)
        for (j = 0; j < nl; j++)
        {
            F[i][j] = 0.0;
            // Keep reduction serial to preserve FP bit-exact result
            for (k = 0; k < nm; ++k)
            {
#pragma HLS PIPELINE II=1
                F[i][j] += C[i][k] * D[k][j];
            }
        }

    // G = E * F  (ni x nl) = (ni x nj) * (nj x nl)
    for (i = 0; i < ni; i++)
        for (j = 0; j < nl; j++)
        {
            G[i][j] = 0.0;
            // Keep reduction serial to preserve FP bit-exact result
            for (k = 0; k < nj; ++k)
            {
#pragma HLS PIPELINE II=1
                G[i][j] += E[i][k] * F[k][j];
            }
        }
}

} // extern "C"

#include "atax.h"

extern "C" {

void kernel_atax(
    double A[M + 0][N + 0],
    double x[N + 0],
    double y[N + 0],
    double tmp[M + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=x      bundle=control
#pragma HLS INTERFACE s_axilite port=y      bundle=control
#pragma HLS INTERFACE s_axilite port=tmp    bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers to avoid repeated global memory traffic
    double l_x[N];
    double l_y[N];
    double l_tmp[M];

#pragma HLS ARRAY_PARTITION variable=l_x   cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=l_y   cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=l_tmp cyclic factor=4 dim=1

    int i, j;

    // Load x from global memory
    load_x: for (j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        l_x[j] = x[j];
    }

    // Initialize y
    init_y: for (i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        l_y[i] = 0.0;
    }

    // Main computation
    outer: for (i = 0; i < M; i++) {
        double tmp_i = 0.0;

        // Compute tmp[i] = A[i][:] * x[:]
        // Serial FP reduction — do NOT unroll to preserve bit-exact order
        inner1: for (j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            tmp_i = tmp_i + A[i][j] * l_x[j];
        }
        l_tmp[i] = tmp_i;

        // Accumulate y[j] += A[i][j] * tmp[i]
        // Serial FP reduction — do NOT unroll to preserve bit-exact order
        inner2: for (j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            l_y[j] = l_y[j] + A[i][j] * tmp_i;
        }
    }

    // Write tmp to global memory
    store_tmp: for (i = 0; i < M; i++) {
#pragma HLS PIPELINE II=1
        tmp[i] = l_tmp[i];
    }

    // Write y to global memory
    store_y: for (j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        y[j] = l_y[j];
    }
}

} // extern "C"

#include "bicg.h"

extern "C" {

void kernel_bicg(
        double A[N + 0][M + 0],
        double s[M + 0],
        double q[N + 0],
        double p[M + 0],
        double r[N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=s offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=q offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=p offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=r offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=s bundle=control
#pragma HLS INTERFACE s_axilite port=q bundle=control
#pragma HLS INTERFACE s_axilite port=p bundle=control
#pragma HLS INTERFACE s_axilite port=r bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int m = M;

    // Local buffers to avoid repeated global memory reads and enable pipelining
    double s_local[M];
    double q_local[N];
    double p_local[M];
    double r_local[N];

#pragma HLS ARRAY_PARTITION variable=s_local cyclic factor=1 dim=1
#pragma HLS ARRAY_PARTITION variable=p_local cyclic factor=1 dim=1

    // Load p and r into local buffers
    load_p: for (int j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
        p_local[j] = p[j];
    }

    load_r: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        r_local[i] = r[i];
    }

    // Initialize s_local
    init_s: for (int i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
        s_local[i] = 0.0;
    }

    // Initialize q_local
    init_q: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        q_local[i] = 0.0;
    }

    // Main computation
    // Note: s[j] is accumulated across outer i-loop iterations (loop-carried dep across i),
    // so we keep the outer loop serial. The inner j-loop pipelines safely.
    // q[i] is a reduction over j within each i-iteration — keep serial (FP guard).
    outer: for (int i = 0; i < n; i++) {
        double qi = q_local[i]; // scalar accumulator for q[i]
        double ri = r_local[i];
        inner: for (int j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
            double aij = A[i][j];
            s_local[j] = s_local[j] + ri * aij;
            qi = qi + aij * p_local[j];
        }
        q_local[i] = qi;
    }

    // Write s_local back to global
    store_s: for (int j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
        s[j] = s_local[j];
    }

    // Write q_local back to global
    store_q: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        q[i] = q_local[i];
    }
}

} // extern "C"

#include "cholesky.h"

extern "C" {

void kernel_cholesky(
		     double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    int i, j, k;

    for (i = 0; i < n; i++) {

        for (j = 0; j < i; j++) {
            for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
                A[i][j] -= A[i][k] * A[j][k];
            }
            A[i][j] /= A[j][j];
        }

        for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
            A[i][i] -= A[i][k] * A[i][k];
        }
        A[i][i] = sqrt(A[i][i]);
    }

}

} // extern "C"

#include "correlation.h"

extern "C" {

void kernel_correlation(
            double float_n,
            double data[N + 0][M + 0],
            double corr[M + 0][M + 0],
            double mean[M + 0],
            double stddev[M + 0])
{
    #pragma HLS INTERFACE s_axilite port=return bundle=control
    #pragma HLS INTERFACE s_axilite port=float_n bundle=control
    #pragma HLS INTERFACE m_axi port=data   offset=slave bundle=gmem
    #pragma HLS INTERFACE m_axi port=corr   offset=slave bundle=gmem
    #pragma HLS INTERFACE m_axi port=mean   offset=slave bundle=gmem
    #pragma HLS INTERFACE m_axi port=stddev offset=slave bundle=gmem
    #pragma HLS INTERFACE s_axilite port=data   bundle=control
    #pragma HLS INTERFACE s_axilite port=corr   bundle=control
    #pragma HLS INTERFACE s_axilite port=mean   bundle=control
    #pragma HLS INTERFACE s_axilite port=stddev bundle=control

    // Local buffers for intermediate values to enable parallel access
    double local_mean[M];
    double local_stddev[M];
    double local_data[N][M];

    #pragma HLS ARRAY_PARTITION variable=local_mean   complete dim=1
    #pragma HLS ARRAY_PARTITION variable=local_stddev complete dim=1
    #pragma HLS ARRAY_PARTITION variable=local_data   cyclic factor=8 dim=2

    const int n = N;
    const int m = M;

    double eps = 0.1;

    // Load data into local buffer
    for (int i = 0; i < n; i++) {
        #pragma HLS PIPELINE II=1
        for (int j = 0; j < m; j++) {
            local_data[i][j] = data[i][j];
        }
    }

    // Compute mean for each column
    for (int j = 0; j < m; j++) {
        local_mean[j] = 0.0;
        for (int i = 0; i < n; i++) {
            #pragma HLS PIPELINE II=1
            local_mean[j] += local_data[i][j];
        }
        local_mean[j] /= float_n;
    }

    // Compute stddev for each column
    for (int j = 0; j < m; j++) {
        local_stddev[j] = 0.0;
        for (int i = 0; i < n; i++) {
            #pragma HLS PIPELINE II=1
            local_stddev[j] += (local_data[i][j] - local_mean[j]) *
                               (local_data[i][j] - local_mean[j]);
        }
        local_stddev[j] /= float_n;
        local_stddev[j] = sqrt(local_stddev[j]);
        local_stddev[j] = local_stddev[j] <= eps ? 1.0 : local_stddev[j];
    }

    // Normalize data
    double sqrt_float_n = sqrt(float_n);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            #pragma HLS PIPELINE II=1
            local_data[i][j] -= local_mean[j];
            local_data[i][j] /= sqrt_float_n * local_stddev[j];
        }
    }

    // Compute correlation matrix
    for (int i = 0; i < m - 1; i++) {
        corr[i][i] = 1.0;
        for (int j = i + 1; j < m; j++) {
            double acc = 0.0;
            for (int k = 0; k < n; k++) {
                #pragma HLS PIPELINE II=1
                acc += local_data[k][i] * local_data[k][j];
            }
            corr[i][j] = acc;
            corr[j][i] = acc;
        }
    }
    corr[m - 1][m - 1] = 1.0;

    // Write back mean and stddev
    for (int j = 0; j < m; j++) {
        #pragma HLS PIPELINE II=1
        mean[j]   = local_mean[j];
        stddev[j] = local_stddev[j];
    }
}

} // extern "C"

#include "covariance.h"

extern "C" {

void kernel_covariance(
		       double float_n,
		       double data[ N + 0][M + 0],
		       double cov[ M + 0][M + 0],
		       double mean[ M + 0])
{
    #pragma HLS INTERFACE m_axi port=data   offset=slave bundle=gmem
    #pragma HLS INTERFACE m_axi port=cov    offset=slave bundle=gmem
    #pragma HLS INTERFACE m_axi port=mean   offset=slave bundle=gmem
    #pragma HLS INTERFACE s_axilite port=float_n bundle=control
    #pragma HLS INTERFACE s_axilite port=data    bundle=control
    #pragma HLS INTERFACE s_axilite port=cov     bundle=control
    #pragma HLS INTERFACE s_axilite port=mean    bundle=control
    #pragma HLS INTERFACE s_axilite port=return  bundle=control

    const int n = N;
    const int m = M;

    // Local buffers for data and mean to reduce global memory pressure
    double local_data[N][M];
    double local_mean[M];
    double local_cov[M][M];

    #pragma HLS ARRAY_PARTITION variable=local_mean complete dim=1
    #pragma HLS ARRAY_PARTITION variable=local_data cyclic factor=8 dim=2
    #pragma HLS ARRAY_PARTITION variable=local_cov  cyclic factor=8 dim=2

    int i, j, k;

    // Load data from global memory
    for (i = 0; i < n; i++) {
        for (j = 0; j < m; j++) {
            #pragma HLS PIPELINE II=1
            local_data[i][j] = data[i][j];
        }
    }

    // Compute mean: serial FP reduction - keep ordering, pipeline body
    for (j = 0; j < m; j++) {
        local_mean[j] = 0.0;
        for (i = 0; i < n; i++) {
            #pragma HLS PIPELINE II=1
            // Serial FP reduction: do NOT unroll/reorder
            local_mean[j] += local_data[i][j];
        }
        local_mean[j] /= float_n;
    }

    // Subtract mean from data
    for (i = 0; i < n; i++) {
        for (j = 0; j < m; j++) {
            #pragma HLS PIPELINE II=1
            local_data[i][j] -= local_mean[j];
        }
    }

    // Compute covariance: serial FP reduction in k - do NOT unroll/reorder
    for (i = 0; i < m; i++) {
        for (j = i; j < m; j++) {
            local_cov[i][j] = 0.0;
            for (k = 0; k < n; k++) {
                #pragma HLS PIPELINE II=1
                // Serial FP reduction: preserve order for bit-exact correctness
                local_cov[i][j] += local_data[k][i] * local_data[k][j];
            }
            local_cov[i][j] /= (float_n - 1.0);
            local_cov[j][i] = local_cov[i][j];
        }
    }

    // Write mean to global memory
    for (j = 0; j < m; j++) {
        #pragma HLS PIPELINE II=1
        mean[j] = local_mean[j];
    }

    // Write cov to global memory
    for (i = 0; i < m; i++) {
        for (j = 0; j < m; j++) {
            #pragma HLS PIPELINE II=1
            cov[i][j] = local_cov[i][j];
        }
    }

    // Write data back to global memory (modified in place)
    for (i = 0; i < n; i++) {
        for (j = 0; j < m; j++) {
            #pragma HLS PIPELINE II=1
            data[i][j] = local_data[i][j];
        }
    }
}

} // extern "C"

#include "doitgen.h"

extern "C" {

void kernel_doitgen(  
		    double A[ NR + 0][NQ + 0][NP + 0],
		    double C4[ NP + 0][NP + 0],
		    double sum[ NP + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=C4  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=sum offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=C4     bundle=control
#pragma HLS INTERFACE s_axilite port=sum    bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int nr = NR;
    const int nq = NQ;
    const int np = NP;

    // Local buffers to avoid repeated global memory traffic
    double local_A[NR][NQ][NP];
    double local_C4[NP][NP];
    double local_sum[NP];

#pragma HLS ARRAY_PARTITION variable=local_sum complete dim=1
#pragma HLS ARRAY_PARTITION variable=local_A   cyclic factor=2 dim=3
#pragma HLS ARRAY_PARTITION variable=local_C4  cyclic factor=2 dim=2

    // Load A from global memory
    for (int r = 0; r < nr; r++)
        for (int q = 0; q < nq; q++)
            for (int p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
                local_A[r][q][p] = A[r][q][p];
            }

    // Load C4 from global memory
    for (int s = 0; s < np; s++)
        for (int p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
            local_C4[s][p] = C4[s][p];
        }

    int r, q, p, s;

    for (r = 0; r < nr; r++)
        for (q = 0; q < nq; q++) {
            // Compute sum[p] for all p
            for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
                local_sum[p] = 0.0;
            }
            // Serial FP reduction over s — do NOT unroll s loop (bit-exact preservation)
            for (s = 0; s < np; s++) {
                for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
                    local_sum[p] += local_A[r][q][s] * local_C4[s][p];
                }
            }
            // Write sum back to A
            for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
                local_A[r][q][p] = local_sum[p];
            }
        }

    // Store A back to global memory
    for (int r2 = 0; r2 < nr; r2++)
        for (int q2 = 0; q2 < nq; q2++)
            for (int p2 = 0; p2 < np; p2++) {
#pragma HLS PIPELINE II=1
                A[r2][q2][p2] = local_A[r2][q2][p2];
            }

    // Write final sum to global memory (last r,q iteration)
    for (int p2 = 0; p2 < np; p2++) {
#pragma HLS PIPELINE II=1
        sum[p2] = local_sum[p2];
    }
}

} // extern "C"

#include "durbin.h"

void kernel_durbin(
		   double r[ N + 0],
		   double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=r offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=r bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    double z[N];
    double alpha;
    double beta;
    double sum;

#pragma HLS ARRAY_PARTITION variable=z cyclic factor=4 dim=1

    int i, k;

    y[0] = -r[0];
    beta = 1.0;
    alpha = -r[0];

    for (k = 1; k < n; k++) {
        beta = (1 - alpha * alpha) * beta;
        sum = 0.0;
        // Serial FP reduction: do NOT unroll/reassociate (bit-exact requirement)
        for (i = 0; i < k; i++) {
#pragma HLS PIPELINE II=1
            sum += r[k - i - 1] * y[i];
        }
        alpha = -(r[k] + sum) / beta;

        for (i = 0; i < k; i++) {
#pragma HLS PIPELINE II=1
            z[i] = y[i] + alpha * y[k - i - 1];
        }
        for (i = 0; i < k; i++) {
#pragma HLS PIPELINE II=1
            y[i] = z[i];
        }
        y[k] = alpha;
    }
}

#include "fdtd-2d.h"

extern "C" {

void kernel_fdtd_2d(
		    double ex[ NX + 0][NY + 0],
		    double ey[ NX + 0][NY + 0],
		    double hz[ NX + 0][NY + 0],
		    double _fict_[ TMAX + 0])
{
#pragma HLS INTERFACE m_axi port=ex      offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=ey      offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=hz      offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=_fict_  offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=ex      bundle=control
#pragma HLS INTERFACE s_axilite port=ey      bundle=control
#pragma HLS INTERFACE s_axilite port=hz      bundle=control
#pragma HLS INTERFACE s_axilite port=_fict_  bundle=control
#pragma HLS INTERFACE s_axilite port=return  bundle=control

    const int tmax = TMAX;
    const int nx   = NX;
    const int ny   = NY;

    // Local copies to enable full array partitioning for parallel access
    double l_ex[NX][NY];
    double l_ey[NX][NY];
    double l_hz[NX][NY];
    double l_fict[TMAX];

#pragma HLS ARRAY_PARTITION variable=l_ex   cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_ey   cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_hz   cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_fict complete dim=1

    // Load _fict_
    for (int t = 0; t < tmax; t++) {
#pragma HLS PIPELINE II=1
        l_fict[t] = _fict_[t];
    }

    // Load ex
    for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            l_ex[i][j] = ex[i][j];
        }
    }

    // Load ey
    for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            l_ey[i][j] = ey[i][j];
        }
    }

    // Load hz
    for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            l_hz[i][j] = hz[i][j];
        }
    }

    int t, i, j;

    for (t = 0; t < tmax; t++) {

        // Update ey[0][j] = _fict_[t]
        for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            l_ey[0][j] = l_fict[t];
        }

        // Update ey[i][j] for i >= 1
        for (i = 1; i < nx; i++) {
            for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
                l_ey[i][j] = l_ey[i][j] - 0.5 * (l_hz[i][j] - l_hz[i-1][j]);
            }
        }

        // Update ex[i][j] for j >= 1
        for (i = 0; i < nx; i++) {
            for (j = 1; j < ny; j++) {
#pragma HLS PIPELINE II=1
                l_ex[i][j] = l_ex[i][j] - 0.5 * (l_hz[i][j] - l_hz[i][j-1]);
            }
        }

        // Update hz[i][j]
        for (i = 0; i < nx - 1; i++) {
            for (j = 0; j < ny - 1; j++) {
#pragma HLS PIPELINE II=1
                l_hz[i][j] = l_hz[i][j] - 0.7 * (l_ex[i][j+1] - l_ex[i][j] +
                                                    l_ey[i+1][j] - l_ey[i][j]);
            }
        }
    }

    // Store ex
    for (i = 0; i < nx; i++) {
        for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            ex[i][j] = l_ex[i][j];
        }
    }

    // Store ey
    for (i = 0; i < nx; i++) {
        for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            ey[i][j] = l_ey[i][j];
        }
    }

    // Store hz
    for (i = 0; i < nx; i++) {
        for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            hz[i][j] = l_hz[i][j];
        }
    }
}

