#include "floyd-warshall.h"

extern "C" {

void kernel_floyd_warshall(int path[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem depth=32400
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    // Local buffer for the k-th row (path[k][*]) to avoid repeated global reads
    int path_k[N];
#pragma HLS ARRAY_PARTITION variable=path_k complete dim=1

    int i, j, k;

    for (k = 0; k < n; k++)
    {
        // Load row k into local buffer
        load_k: for (j = 0; j < n; j++)
        {
#pragma HLS PIPELINE II=1
            path_k[j] = path[k][j];
        }

        // Update all paths using row k
        loop_i: for (i = 0; i < n; i++)
        {
            // Cache path[i][k] as a scalar to avoid repeated global memory reads in j-loop
            int path_ik = path[i][k];

            loop_j: for (j = 0; j < n; j++)
            {
#pragma HLS PIPELINE II=1
                int old_val  = path[i][j];
                int new_val  = path_ik + path_k[j];
                path[i][j]   = old_val < new_val ? old_val : new_val;
            }
        }
    }
}

} // extern "C"

#include "gemm.h"

extern "C" {

void kernel_gemm(
		 double alpha,
		 double beta,
		 double C[ NI + 0][NJ + 0],
		 double A[ NI + 0][NK + 0],
		 double B[ NK + 0][NJ + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=C     bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=B     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local copies to avoid repeated global-memory traffic and enable
    // partitioning for pipelined access
    double l_C[NI][NJ];
    double l_A[NI][NK];
    double l_B[NK][NJ];

#pragma HLS ARRAY_PARTITION variable=l_C cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_A cyclic factor=1 dim=2
#pragma HLS ARRAY_PARTITION variable=l_B cyclic factor=8 dim=2

    // Load C
    for (int i = 0; i < NI; i++) {
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            l_C[i][j] = C[i][j];
        }
    }

    // Load A
    for (int i = 0; i < NI; i++) {
        for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
            l_A[i][k] = A[i][k];
        }
    }

    // Load B
    for (int k = 0; k < NK; k++) {
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            l_B[k][j] = B[k][j];
        }
    }

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;

    int i, j, k;

    // Compute: scale C by beta, then accumulate alpha*A*B
    for (i = 0; i < ni; i++) {
        // Scale C[i][j] *= beta
        for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            l_C[i][j] *= beta;
        }
        // Accumulate: C[i][j] += alpha * A[i][k] * B[k][j]
        // k is the reduction dimension — do NOT unroll k (FP reduction order must be preserved)
        for (k = 0; k < nk; k++) {
            double a_ik = l_A[i][k];
            for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
                l_C[i][j] += alpha * a_ik * l_B[k][j];
            }
        }
    }

    // Store C
    for (int i = 0; i < NI; i++) {
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = l_C[i][j];
        }
    }
}

} // extern "C"

#include "gemver.h"

extern "C" {

void kernel_gemver(
		   double alpha,
		   double beta,
		   double A[ N + 0][N + 0],
		   double u1[ N + 0],
		   double v1[ N + 0],
		   double u2[ N + 0],
		   double v2[ N + 0],
		   double w[ N + 0],
		   double x[ N + 0],
		   double y[ N + 0],
		   double z[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=u1  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=v1  offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=u2  offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=v2  offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=w   offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem6
#pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem7
#pragma HLS INTERFACE m_axi port=z   offset=slave bundle=gmem8

#pragma HLS INTERFACE s_axilite port=alpha  bundle=control
#pragma HLS INTERFACE s_axilite port=beta   bundle=control
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=u1     bundle=control
#pragma HLS INTERFACE s_axilite port=v1     bundle=control
#pragma HLS INTERFACE s_axilite port=u2     bundle=control
#pragma HLS INTERFACE s_axilite port=v2     bundle=control
#pragma HLS INTERFACE s_axilite port=w      bundle=control
#pragma HLS INTERFACE s_axilite port=x      bundle=control
#pragma HLS INTERFACE s_axilite port=y      bundle=control
#pragma HLS INTERFACE s_axilite port=z      bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    int i, j;

    // Local caches for 1D arrays to reduce global memory traffic
    double u1_local[N];
    double v1_local[N];
    double u2_local[N];
    double v2_local[N];
    double x_local[N];
    double y_local[N];
    double z_local[N];
    double w_local[N];

#pragma HLS ARRAY_PARTITION variable=u1_local complete dim=1
#pragma HLS ARRAY_PARTITION variable=v1_local complete dim=1
#pragma HLS ARRAY_PARTITION variable=u2_local complete dim=1
#pragma HLS ARRAY_PARTITION variable=v2_local complete dim=1
#pragma HLS ARRAY_PARTITION variable=x_local  complete dim=1
#pragma HLS ARRAY_PARTITION variable=y_local  complete dim=1
#pragma HLS ARRAY_PARTITION variable=z_local  complete dim=1
#pragma HLS ARRAY_PARTITION variable=w_local  complete dim=1

    // Load 1D arrays from global memory
    load_u1: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        u1_local[i] = u1[i];
    }
    load_v1: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        v1_local[i] = v1[i];
    }
    load_u2: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        u2_local[i] = u2[i];
    }
    load_v2: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        v2_local[i] = v2[i];
    }
    load_x: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x_local[i] = x[i];
    }
    load_y: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        y_local[i] = y[i];
    }
    load_z: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        z_local[i] = z[i];
    }
    load_w: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        w_local[i] = w[i];
    }

    // Loop 1: A[i][j] += u1[i]*v1[j] + u2[i]*v2[j]
    // No reduction — each element independent, pipeline inner loop
    loop1_i: for (i = 0; i < n; i++) {
        loop1_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = A[i][j] + u1_local[i] * v1_local[j] + u2_local[i] * v2_local[j];
        }
    }

    // Loop 2: x[i] += beta * A[j][i] * y[j]  (serial FP reduction over j)
    // Must keep reduction serial — no unroll on j
    loop2_i: for (i = 0; i < n; i++) {
        loop2_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            x_local[i] = x_local[i] + beta * A[j][i] * y_local[j];
        }
    }

    // Loop 3: x[i] += z[i]  (independent per i)
    loop3: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x_local[i] = x_local[i] + z_local[i];
    }

    // Loop 4: w[i] += alpha * A[i][j] * x[j]  (serial FP reduction over j)
    // Must keep reduction serial — no unroll on j
    loop4_i: for (i = 0; i < n; i++) {
        loop4_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            w_local[i] = w_local[i] + alpha * A[i][j] * x_local[j];
        }
    }

    // Store results back to global memory
    store_x: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x[i] = x_local[i];
    }
    store_w: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        w[i] = w_local[i];
    }
}

} // extern "C"

#include "gesummv.h"

extern "C" {

void kernel_gesummv(
		    double alpha,
		    double beta,
		    double A[ N + 0][N + 0],
		    double B[ N + 0][N + 0],
		    double tmp[ N + 0],
		    double x[ N + 0],
		    double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=alpha  bundle=control
#pragma HLS INTERFACE s_axilite port=beta   bundle=control
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=B      bundle=control
#pragma HLS INTERFACE s_axilite port=tmp    bundle=control
#pragma HLS INTERFACE s_axilite port=x      bundle=control
#pragma HLS INTERFACE s_axilite port=y      bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    // Local copies of x to allow reuse across iterations
    double x_local[N];
    #pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=4 dim=1

    // Load x into local buffer once
    for (int k = 0; k < n; k++) {
        #pragma HLS PIPELINE II=1
        x_local[k] = x[k];
    }

    int i, j;

    for (i = 0; i < n; i++)
    {
        // Use local scalar accumulators to preserve exact FP reduction order
        double tmp_i = 0.0;
        double y_i   = 0.0;

        for (j = 0; j < n; j++)
        {
            #pragma HLS PIPELINE II=1
            // Serial FP reduction: order preserved, no reassociation
            tmp_i = A[i][j] * x_local[j] + tmp_i;
            y_i   = B[i][j] * x_local[j] + y_i;
        }

        y_i     = alpha * tmp_i + beta * y_i;
        tmp[i]  = tmp_i;
        y[i]    = y_i;
    }

}

} // extern "C"

#include "gramschmidt.h"

extern "C" {

void kernel_gramschmidt(
        double A[M + 0][N + 0],
        double R[N + 0][N + 0],
        double Q[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=R offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=Q offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=R bundle=control
#pragma HLS INTERFACE s_axilite port=Q bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local copies for better data reuse and partitioning
    double lA[M][N];
    double lR[N][N];
    double lQ[M][N];

#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=lR cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=lQ cyclic factor=4 dim=2

    // Load A into local buffer
    for (int i = 0; i < M; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            lA[i][j] = A[i][j];
        }
    }

    const int m = M;
    const int n = N;

    int i, j, k;
    double nrm;

    for (k = 0; k < n; k++) {
        // FP reduction: keep serial, pipeline the loop body only
        nrm = 0.0;
        for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
            nrm += lA[i][k] * lA[i][k];
        }

        lR[k][k] = sqrt(nrm);

        // Normalize column: independent iterations, safe to pipeline
        for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
            lQ[i][k] = lA[i][k] / lR[k][k];
        }

        for (j = k + 1; j < n; j++) {
            // FP reduction: keep serial, pipeline the loop body only
            lR[k][j] = 0.0;
            for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
                lR[k][j] += lQ[i][k] * lA[i][j];
            }

            // Update A column: independent iterations, safe to pipeline
            for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
                lA[i][j] = lA[i][j] - lQ[i][k] * lR[k][j];
            }
        }
    }

    // Write back results
    for (int i = 0; i < M; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            A[i][j] = lA[i][j];
        }
    }

    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            R[i][j] = lR[i][j];
        }
    }

    for (int i = 0; i < M; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            Q[i][j] = lQ[i][j];
        }
    }
}

} // extern "C"

#include "jacobi-1d.h"

extern "C" {

void kernel_jacobi_1d(
                double A[N + 0],
                double B[N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int tsteps = TSTEPS;

    // Local buffers to enable pipelining and avoid global memory hazards
    double lA[N];
    double lB[N];

#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=lB cyclic factor=4 dim=1

    // Load A into local buffer
    load_A: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        lA[i] = A[i];
    }

    // Load B into local buffer
    load_B: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        lB[i] = B[i];
    }

    int t, i;

    for (t = 0; t < tsteps; t++) {
        // B[i] = 0.33333 * (A[i-1] + A[i] + A[i+1])
        stencil_B: for (i = 1; i < n - 1; i++) {
#pragma HLS PIPELINE II=1
            lB[i] = 0.33333 * (lA[i-1] + lA[i] + lA[i + 1]);
        }
        // A[i] = 0.33333 * (B[i-1] + B[i] + B[i+1])
        stencil_A: for (i = 1; i < n - 1; i++) {
#pragma HLS PIPELINE II=1
            lA[i] = 0.33333 * (lB[i-1] + lB[i] + lB[i + 1]);
        }
    }

    // Store local A back to global
    store_A: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        A[i] = lA[i];
    }

    // Store local B back to global
    store_B: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        B[i] = lB[i];
    }
}

} // extern "C"

#include "jacobi-2d.h"

extern "C" {

void kernel_jacobi_2d(
                double A[N + 0][N + 0],
                double B[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int tsteps = TSTEPS;

    // Local ping-pong buffers to avoid global memory stencil hazards
    double lA[N][N];
    double lB[N][N];
#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=lB cyclic factor=4 dim=2

    // Load A into local buffer
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            lA[i][j] = A[i][j];
        }
    }

    int t, i, j;

    for (t = 0; t < tsteps; t++) {
        // First stencil: A -> B
        for (i = 1; i < n - 1; i++) {
            for (j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
                lB[i][j] = 0.2 * (lA[i][j] + lA[i][j-1] + lA[i][1+j] + lA[1+i][j] + lA[i-1][j]);
            }
        }
        // Second stencil: B -> A
        for (i = 1; i < n - 1; i++) {
            for (j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
                lA[i][j] = 0.2 * (lB[i][j] + lB[i][j-1] + lB[i][1+j] + lB[1+i][j] + lB[i-1][j]);
            }
        }
    }

    // Write back results
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = lA[i][j];
            B[i][j] = lB[i][j];
        }
    }
}

} // extern "C"

#include "lu.h"

extern "C" {

void kernel_lu(
               double A[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

#pragma HLS ARRAY_PARTITION variable=A cyclic factor=8 dim=2

    const int n = N;

    int i, j, k;

    for (i = 0; i < n; i++) {
        for (j = 0; j < i; j++) {
            for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
                A[i][j] -= A[i][k] * A[k][j];
            }
            A[i][j] /= A[j][j];
        }
        for (j = i; j < n; j++) {
            for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
                A[i][j] -= A[i][k] * A[k][j];
            }
        }
    }
}

} // extern "C"

#include "ludcmp.h"

extern "C" {

void kernel_ludcmp(
		   double A[ N + 0][N + 0],
		   double b[ N + 0],
		   double x[ N + 0],
		   double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=b offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=b bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local copies to enable fast on-chip access and partitioning
    double lA[N][N];
    double lb[N];
    double lx[N];
    double ly[N];

#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=lb cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=lx cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=ly cyclic factor=8 dim=1

    // Load A from global memory
    load_A_outer: for (int i = 0; i < N; i++) {
        load_A_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            lA[i][j] = A[i][j];
        }
    }

    // Load b
    load_b: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        lb[i] = b[i];
    }

    // Load x
    load_x: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        lx[i] = x[i];
    }

    // Load y
    load_y: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        ly[i] = y[i];
    }

    const int n = N;
    int i, j, k;
    double w;

    // LU decomposition
    for (i = 0; i < n; i++) {
        for (j = 0; j < i; j++) {
            w = lA[i][j];
            for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
                w -= lA[i][k] * lA[k][j];
            }
            lA[i][j] = w / lA[j][j];
        }
        for (j = i; j < n; j++) {
            w = lA[i][j];
            for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
                w -= lA[i][k] * lA[k][j];
            }
            lA[i][j] = w;
        }
    }

    // Forward substitution: solve L*y = b
    for (i = 0; i < n; i++) {
        w = lb[i];
        for (j = 0; j < i; j++) {
#pragma HLS PIPELINE II=1
            w -= lA[i][j] * ly[j];
        }
        ly[i] = w;
    }

    // Backward substitution: solve U*x = y
    for (i = n-1; i >= 0; i--) {
        w = ly[i];
        for (j = i+1; j < n; j++) {
#pragma HLS PIPELINE II=1
            w -= lA[i][j] * lx[j];
        }
        lx[i] = w / lA[i][i];
    }

    // Write back A
    store_A_outer: for (int i = 0; i < N; i++) {
        store_A_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = lA[i][j];
        }
    }

    // Write back b
    store_b: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        b[i] = lb[i];
    }

    // Write back x
    store_x: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        x[i] = lx[i];
    }

    // Write back y
    store_y: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        y[i] = ly[i];
    }
}

} // extern "C"

#include "mvt.h"

// The kernel_mvt signature is declared in mvt.h and defined here.
// We preserve the algorithm exactly (serial FP reduction — no reassociation).
void kernel_mvt(
        double x1[ N + 0],
        double x2[ N + 0],
        double y_1[ N + 0],
        double y_2[ N + 0],
        double A[ N + 0][N + 0])
{
#pragma HLS INLINE off

    // Partition local-access arrays for parallel read inside pipelined inner loops
#pragma HLS ARRAY_PARTITION variable=x1  complete dim=1
#pragma HLS ARRAY_PARTITION variable=x2  complete dim=1
#pragma HLS ARRAY_PARTITION variable=y_1 complete dim=1
#pragma HLS ARRAY_PARTITION variable=y_2 complete dim=1
    // Cyclic partition of A on dim=2 (column) so consecutive j-accesses hit
    // different banks; dim=1 cyclic helps the transpose loop (A[j][i]).
#pragma HLS ARRAY_PARTITION variable=A cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=A cyclic factor=8 dim=1

    const int n = N;

    int i, j;

    // Loop 1: x1[i] += A[i][j] * y_1[j]  — serial FP reduction over j
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            x1[i] = x1[i] + A[i][j] * y_1[j];
        }
    }

    // Loop 2: x2[i] += A[j][i] * y_2[j]  — serial FP reduction over j
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            x2[i] = x2[i] + A[j][i] * y_2[j];
        }
    }
}

// Top-level workload wrapper with AXI interfaces for Vitis HLS / Alveo U280
extern "C" {
void workload(
        double x1[ N + 0],
        double x2[ N + 0],
        double y_1[ N + 0],
        double y_2[ N + 0],
        double A[ N * N])   // flattened for m_axi port
{
#pragma HLS INTERFACE m_axi port=x1  offset=slave bundle=gmem0 depth=120
#pragma HLS INTERFACE m_axi port=x2  offset=slave bundle=gmem1 depth=120
#pragma HLS INTERFACE m_axi port=y_1 offset=slave bundle=gmem2 depth=120
#pragma HLS INTERFACE m_axi port=y_2 offset=slave bundle=gmem3 depth=120
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem4 depth=14400

#pragma HLS INTERFACE s_axilite port=x1     bundle=control
#pragma HLS INTERFACE s_axilite port=x2     bundle=control
#pragma HLS INTERFACE s_axilite port=y_1    bundle=control
#pragma HLS INTERFACE s_axilite port=y_2    bundle=control
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers to stage data from global memory
    double lx1[N], lx2[N], ly1[N], ly2[N];
    double lA[N][N];

#pragma HLS ARRAY_PARTITION variable=lx1 complete dim=1
#pragma HLS ARRAY_PARTITION variable=lx2 complete dim=1
#pragma HLS ARRAY_PARTITION variable=ly1 complete dim=1
#pragma HLS ARRAY_PARTITION variable=ly2 complete dim=1
#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=8 dim=1

    // Load x1
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        lx1[i] = x1[i];
    }
    // Load x2
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        lx2[i] = x2[i];
    }
    // Load y_1
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        ly1[i] = y_1[i];
    }
    // Load y_2
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        ly2[i] = y_2[i];
    }
    // Load A (flattened)
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            lA[i][j] = A[i * N + j];
        }
    }

    // Compute using the original kernel
    kernel_mvt(lx1, lx2, ly1, ly2, lA);

    // Store x1 back
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        x1[i] = lx1[i];
    }
    // Store x2 back
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        x2[i] = lx2[i];
    }
}
