#include "nussinov.h"

extern "C" {

void kernel_nussinov( char seq[ N + 0],
                      int table[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=seq    offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=table offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=seq    bundle=control
#pragma HLS INTERFACE s_axilite port=table  bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local copies for faster access
    char  l_seq[N];
    int   l_table[N][N];

#pragma HLS ARRAY_PARTITION variable=l_seq   complete dim=1
#pragma HLS ARRAY_PARTITION variable=l_table cyclic factor=8 dim=2

    // Load seq
    for (int ii = 0; ii < N; ii++) {
#pragma HLS PIPELINE II=1
        l_seq[ii] = seq[ii];
    }

    // Load table
    for (int ii = 0; ii < N; ii++) {
        for (int jj = 0; jj < N; jj++) {
#pragma HLS PIPELINE II=1
            l_table[ii][jj] = table[ii][jj];
        }
    }

    // --- Original algorithm (logic unchanged) ---
    const int n = N;
    int i, j, k;

    for (i = n-1; i >= 0; i--) {
        for (j = i+1; j < n; j++) {

            if (j-1 >= 0)
                l_table[i][j] = ((l_table[i][j] >= l_table[i][j-1]) ? l_table[i][j] : l_table[i][j-1]);
            if (i+1 < n)
                l_table[i][j] = ((l_table[i][j] >= l_table[i+1][j]) ? l_table[i][j] : l_table[i+1][j]);

            if (j-1 >= 0 && i+1 < n) {
                if (i < j-1)
                    l_table[i][j] = ((l_table[i][j] >= l_table[i+1][j-1]+(((l_seq[i])+(l_seq[j])) == 3 ? 1 : 0)) ? l_table[i][j] : l_table[i+1][j-1]+(((l_seq[i])+(l_seq[j])) == 3 ? 1 : 0));
                else
                    l_table[i][j] = ((l_table[i][j] >= l_table[i+1][j-1]) ? l_table[i][j] : l_table[i+1][j-1]);
            }

            for (k = i+1; k < j; k++) {
#pragma HLS PIPELINE II=1
                l_table[i][j] = ((l_table[i][j] >= l_table[i][k] + l_table[k+1][j]) ? l_table[i][j] : l_table[i][k] + l_table[k+1][j]);
            }
        }
    }

    // Store table back
    for (int ii = 0; ii < N; ii++) {
        for (int jj = 0; jj < N; jj++) {
#pragma HLS PIPELINE II=1
            table[ii][jj] = l_table[ii][jj];
        }
    }
}

} // extern "C"

#include "symm.h"

extern "C" {

void kernel_symm(
        double alpha,
        double beta,
        double C[M][N],
        double A[M][M],
        double B[M][N])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local row buffers to reduce repeated AXI accesses
    double A_row[M];
    double B_i_row[N];
    double C_i_row[N];
    double temp2_arr[N];

#pragma HLS ARRAY_PARTITION variable=A_row complete dim=1
#pragma HLS ARRAY_PARTITION variable=B_i_row complete dim=1
#pragma HLS ARRAY_PARTITION variable=C_i_row complete dim=1
#pragma HLS ARRAY_PARTITION variable=temp2_arr complete dim=1

    const int m = M;
    const int n = N;

    for (int i = 0; i < m; i++) {

        // Load A[i][*] into local buffer
        load_A: for (int k = 0; k < m; k++) {
#pragma HLS PIPELINE II=1
            A_row[k] = A[i][k];
        }

        // Load B[i][*] into local buffer
        load_B_i: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            B_i_row[j] = B[i][j];
        }

        // Load C[i][*] into local buffer
        load_C_i: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            C_i_row[j] = C[i][j];
        }

        // Initialize temp2 accumulators
        init_temp2: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            temp2_arr[j] = 0.0;
        }

        // Inner k loop: for each k < i, update C[k][j] and accumulate temp2
        // Preserve serial FP reduction order (j varies fastest for a fixed k)
        for (int k = 0; k < i; k++) {
            double A_ik = A_row[k];
            double alpha_A_ik = alpha * A_ik;

            // Load B[k][*] row from global memory
            double B_k_row[N];
#pragma HLS ARRAY_PARTITION variable=B_k_row complete dim=1
            load_Bk: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                B_k_row[j] = B[k][j];
            }

            // Load C[k][*] row, update, store back
            double C_k_row[N];
#pragma HLS ARRAY_PARTITION variable=C_k_row complete dim=1
            load_Ck: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                C_k_row[j] = C[k][j];
            }

            // Update C[k][j] and temp2[j] — j iterations independent
            update_j: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                C_k_row[j] += alpha * B_i_row[j] * A_ik;
                temp2_arr[j] += B_k_row[j] * A_ik;
            }

            store_Ck: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                C[k][j] = C_k_row[j];
            }
        }

        // Final update for C[i][j]
        final_update: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            C_i_row[j] = beta * C_i_row[j]
                         + alpha * B_i_row[j] * A_row[i]
                         + alpha * temp2_arr[j];
        }

        // Store C[i][*] back
        store_Ci: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = C_i_row[j];
        }
    }
}

} // extern "C"

#include "syr2k.h"

extern "C" {

void kernel_syr2k(
    double alpha,
    double beta,
    double C[N + 0][N + 0],
    double A[N + 0][M + 0],
    double B[N + 0][M + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers to avoid repeated global memory access and enable partitioning
    double localC[N][N];
    double localA[N][M];
    double localB[N][M];

#pragma HLS ARRAY_PARTITION variable=localC cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=localA cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=localB cyclic factor=8 dim=2

    // Load C into local buffer
    load_C_outer: for (int i = 0; i < N; i++) {
        load_C_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            localC[i][j] = C[i][j];
        }
    }

    // Load A into local buffer
    load_A_outer: for (int i = 0; i < N; i++) {
        load_A_inner: for (int k = 0; k < M; k++) {
#pragma HLS PIPELINE II=1
            localA[i][k] = A[i][k];
        }
    }

    // Load B into local buffer
    load_B_outer: for (int i = 0; i < N; i++) {
        load_B_inner: for (int k = 0; k < M; k++) {
#pragma HLS PIPELINE II=1
            localB[i][k] = B[i][k];
        }
    }

    const int n = N;
    const int m = M;

    int i, j, k;

    // Beta scaling pass
    scale_i: for (i = 0; i < n; i++) {
        scale_j: for (j = 0; j <= i; j++) {
#pragma HLS PIPELINE II=1
            localC[i][j] *= beta;
        }
    }

    // Main computation: keep innermost loop serial for FP bit-exact correctness
    // Pipeline the innermost loop body; do NOT reorder/reassociate the FP reduction
    compute_i: for (i = 0; i < n; i++) {
        compute_k: for (k = 0; k < m; k++) {
            compute_j: for (j = 0; j <= i; j++) {
#pragma HLS PIPELINE II=1
                localC[i][j] += localA[j][k] * alpha * localB[i][k]
                              + localB[j][k] * alpha * localA[i][k];
            }
        }
    }

    // Store C back to global memory
    store_C_outer: for (int i = 0; i < N; i++) {
        store_C_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = localC[i][j];
        }
    }
}

} // extern "C"

#include "syrk.h"

extern "C" {

void kernel_syrk(
        double alpha,
        double beta,
        double C[N + 0][N + 0],
        double A[N + 0][M + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=C     bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int m = M;

    int i, j, k;

    for (i = 0; i < n; i++) {
        // Scale lower-triangular row i by beta
        for (j = 0; j <= i; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] *= beta;
        }
        // Accumulate outer-product contributions — keep FP reduction serial
        for (k = 0; k < m; k++) {
            for (j = 0; j <= i; j++) {
#pragma HLS PIPELINE II=1
                C[i][j] += alpha * A[i][k] * A[j][k];
            }
        }
    }
}

} // extern "C"

#include "trisolv.h"

extern "C" {

void kernel_trisolv(
        double L[N + 0][N + 0],
        double x[N + 0],
        double b[N + 0])
{
    #pragma HLS INTERFACE m_axi port=L offset=slave bundle=gmem0
    #pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem1
    #pragma HLS INTERFACE m_axi port=b offset=slave bundle=gmem2
    #pragma HLS INTERFACE s_axilite port=L bundle=control
    #pragma HLS INTERFACE s_axilite port=x bundle=control
    #pragma HLS INTERFACE s_axilite port=b bundle=control
    #pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers to avoid repeated global memory accesses
    double L_local[N][N];
    double x_local[N];
    double b_local[N];

    #pragma HLS ARRAY_PARTITION variable=L_local cyclic factor=4 dim=2
    #pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=4 dim=1
    #pragma HLS ARRAY_PARTITION variable=b_local complete dim=1

    // Load b into local buffer
    load_b: for (int i = 0; i < N; i++) {
        #pragma HLS PIPELINE II=1
        b_local[i] = b[i];
    }

    // Load L into local buffer
    load_L: for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            #pragma HLS PIPELINE II=1
            L_local[i][j] = L[i][j];
        }
    }

    const int n = N;
    int i, j;

    // Main triangular solve
    // Outer loop has loop-carried dependency on x_local, cannot pipeline
    for (i = 0; i < n; i++) {
        double xi = b_local[i];
        // Inner FP reduction: preserve serial order for bit-exact correctness
        for (j = 0; j < i; j++) {
            #pragma HLS PIPELINE II=1
            xi -= L_local[i][j] * x_local[j];
        }
        x_local[i] = xi / L_local[i][i];
    }

    // Write x back to global memory
    store_x: for (int i = 0; i < N; i++) {
        #pragma HLS PIPELINE II=1
        x[i] = x_local[i];
    }
}

} // extern "C"

#include "trmm.h"

extern "C" {

void kernel_trmm(
        double alpha,
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers to avoid repeated global memory access
    double localA[M][M];
    double localB[M][N];

#pragma HLS ARRAY_PARTITION variable=localA cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=localB cyclic factor=4 dim=2

    // Load A into local buffer
    load_A_i: for (int i = 0; i < M; i++) {
        load_A_j: for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
            localA[i][j] = A[i][j];
        }
    }

    // Load B into local buffer
    load_B_i: for (int i = 0; i < M; i++) {
        load_B_j: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            localB[i][j] = B[i][j];
        }
    }

    // Compute TRMM
    // Preserve original algorithm exactly; pipeline innermost k-loop.
    // The FP reduction in k is serial to maintain bit-exactness.
    const int m = M;
    const int n = N;

    int i, j, k;
    for (i = 0; i < m; i++) {
        for (j = 0; j < n; j++) {
            // Serial FP reduction: do NOT unroll or reorder (bit-exact guard)
            for (k = i + 1; k < m; k++) {
#pragma HLS PIPELINE
                localB[i][j] += localA[k][i] * localB[k][j];
            }
            localB[i][j] = alpha * localB[i][j];
        }
    }

    // Store B back to global memory
    store_B_i: for (int i = 0; i < M; i++) {
        store_B_j: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            B[i][j] = localB[i][j];
        }
    }
}

} // extern "C"
